// Generated once from the standard Generic CMYK ICC profile on macOS.
// A small 9^4 grid keeps PDF DeviceCMYK conversion deterministic in Wasm.

const LEVELS: usize = 9;
const LAST: usize = LEVELS - 1;

pub(super) fn to_srgb(values: [f32; 4]) -> [u8; 3] {
    let coordinates = values.map(|value| value.clamp(0.0, 1.0) * LAST as f32);
    let low = coordinates.map(|value| value.floor() as usize);
    let high = low.map(|value| (value + 1).min(LAST));
    let fraction = std::array::from_fn::<_, 4, _>(|index| coordinates[index] - low[index] as f32);
    let mut result = [0.0_f32; 3];
    for corner in 0..16 {
        let mut weight = 1.0;
        let mut index = 0;
        for component in 0..4 {
            let upper = corner & (1 << component) != 0;
            weight *= if upper {
                fraction[component]
            } else {
                1.0 - fraction[component]
            };
            index = index * LEVELS
                + if upper {
                    high[component]
                } else {
                    low[component]
                };
        }
        let offset = index * 3;
        for channel in 0..3 {
            result[channel] += f32::from(LUT[offset + channel]) * weight;
        }
    }
    result.map(|value| value.round().clamp(0.0, 255.0) as u8)
}

